def solve(g,bg,wall):
    H,W=len(g),len(g[0])
    # find 3-comp and 2-comp
    seen=set(); cs=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] not in (bg,wall) and (r,c) not in seen:
                q=deque([(r,c)]); comp=[]; seen.add((r,c))
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==g[y][x] and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                cs.append((g[r][c],comp))
    c3=[k for k,v in cs if k==3]; c2=[k for k,v in cs if k==2]
    threes=cs[0]; twos=cs[1]
    goals=set()
    for p in threes:
        for q2 in twos:
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                pass
    startset=set(sum([p[1] for p in c3],[])); goalset=set(sum([p[1] for p in c2],[]))
    dist={p:0 for p in startset}; prev={}
    q=deque(startset)
    found=None
    while q:
        y,x=q.popleft()
        if (y,x) in goalset: found=(y,x); break
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and g[ny][nx]==bg and (ny,nx) not in dist:
                dist[(ny,nx)]=dist[(y,x)]+1; prev[(ny,nx)]=(y,x); q.append((ny,nx))
    # reconstruct: try all paths by backtracking with preference order
    out=[]; def backtrack(p,path):
        if p in startset: out.append(list(path)[::-1]); return
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=p[0]+dy,p[1]+dx
            if (ny,nx) in dist and (ny,nx)!=found:
                path.insert(0,(ny,nx)); backtrack((ny,nx),path); path.pop(0)
    backtrack(found,[])
    print(len(out), 'paths, shortest len', dist[found])
    return out
