def shortest_path_cells(g,bg,wall,c3set,c2set):
    H,W=len(g),len(g[0])
    starts={(y,x) for y in range(H) for x in range(W) if g[y][x]==bg and any(abs(y-ry)+abs(x-cx)==1 for ry,cx in c3set)}
    goals=set()
    for (yy,xx) in c2set:
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            y,x=yy+dy,xx+dx
            if 0<=y<H and 0<=x<W and g[y][x]==bg: goals.add((y,x))
    dist={p:0 for p in starts}; prev={}; q=deque(starts); found=None
    while q:
        y,x=q.popleft()
        if (y,x) in goals: found=(y,x); break
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and g[ny][nx]==bg and (ny,nx) not in dist:
                dist[(ny,nx)]=dist[(y,x)]+1; prev[(ny,nx)]=(y,x); q.append((ny,nx))
    # backtrack all shortest paths with a canonical reconstruction (greedy backtracking from found)
    path=[found]; cur=prev[found]
    while cur in dist:
        path.insert(0,cur); cur=prev[cur]
    return path,found,len(path)-1
