def solve(g,bg,draw):
    H,W=len(g),len(g[0])
    th={(r,c) for r in range(H) for c in range(W) if g[r][c]==3}
    tw={(r,c) for r in range(H) for c in range(W) if g[r][c]==2}
    def ok(y,x): return 0<=y<H and 0<=x<W and g[y][x]==bg
    goals=set()
    for yy,xx in tw:
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            y,x=yy+dy,xx+dx
            if ok(y,x): goals.add((y,x))
    dist={}; q=deque(); prev={}
    for yy,xx in th:
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            y,x=yy+dy,xx+dx
            if ok(y,x) and (y,x) not in dist:
                dist[(y,x)]=1; q.append((y,x))
    found=None
    while q:
        y,x=q.popleft()
        if (y,x) in goals: found=(y,x); break
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if ok(ny,nx) and (ny,nx) not in dist:
                dist[(ny,nx)]=dist[(y,x)]+1; prev[(ny,nx)]=(y,x); q.append((ny,nx))
    cand=[]
    # collect all shortest paths by exploring backward from found alternatives: use BFS levels with parent pointers per distance layer instead
    # simpler: enumerate paths of length dist[goal] via backtracking with visited pruning
    best=None
    targets=sorted(goals,key=lambda p:(p[0]+p[1],p))
    for tgt in targets:
        if dist.get(tgt,10**9)!=dist.get(found,0): continue
        # backtrace greedily with branching limited: follow parent chain, allow re-branching only at nodes with multiple parents handled by BFS layers
        p=[tgt]; cur=tgt
        while cur not in dist or cur in set(th):
            n=prev[cur]
            if n is None: break
            p.insert(0,n); cur=n
        sc=sum(y+x for y,x in p)
        cand.append((sc,p))
    cand.sort(key=lambda t:(t[0],len(t[1]),t[1][0]))
    best=cand[0][1]
    out=[row[:] for row in g]
    for (y,x) in best: out[y][x]=draw
    return out,best,tgt
