    def ok(y,x): return 0<=y<H and 0<=x<W and g[y][x]==bg
    parents={}; q=deque(starts); dist={s:0 for s in starts}
    best=None
    # multi-source BFS; stop when any goal reached; track parent pointers
    while q:
