            ny,nx=y+dy,x+dx
            if ok(ny,nx) and (ny,nx) not in dist:
                dist[(ny,nx)]=dist[(y,x)]+1; parents[(ny,nx)]=(y,x); q.append((ny,nx))
                if (ny,nx) in goals:
